__NUXT_JSONP__("/posts/coding-a-custom-banking-card-creation-tool-with-nuxt", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L){return {data:[{post:{slug:s,description:r,title:"Coding a custom banking card creation tool with Nuxt",type:j,imgCover:s,tags:["nuxt","testing","node",t,j],createdAt:"2020-06-05T00:00:00.000Z",toc:[{id:u,depth:k,text:v},{id:w,depth:k,text:x},{id:y,depth:k,text:z},{id:A,depth:k,text:B},{id:C,depth:k,text:D},{id:E,depth:k,text:F},{id:G,depth:k,text:H}],body:{type:I,children:[{type:b,tag:i,props:{},children:[{type:a,value:r}]},{type:a,value:d},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"The project is still in its creation phase, but I'll put here a demo link as soon as it's ready later."}]},{type:a,value:d},{type:b,tag:l,props:{id:u},children:[{type:b,tag:c,props:{href:"#building-the-app",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:v}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"The tool will be used as a web app by sales representatives initally after launch. It might then be offered as a public tool with user authentication. I chose to go with Nuxt.js as it offers more versatility if I ever have to build as a SSR app, even if I’m using the SPA mode as it suits best for this kind of project."}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"Regarding the architecture, it’s a single route getting datas from a Vuex store initially fed with some JSONs , and updating everytime an action is done. Transitions, mutations, nothing special here."}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"User have to choose options such as the Visa logo position, or the stripe color to get forward."}]},{type:a,value:d},{type:b,tag:l,props:{id:w},children:[{type:b,tag:c,props:{href:"#image-handling",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:x}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"User also can upload a background image and set it up in the preview as he would do in photoshop. I used "},{type:b,tag:c,props:{href:"https:\u002F\u002Fgithub.com\u002Frowanwins\u002Fvue-dropzone",rel:[e,f,g],target:h},children:[{type:a,value:"vue-dropzone"}]},{type:a,value:" in combination with "},{type:b,tag:c,props:{href:"https:\u002F\u002Fgithub.com\u002Fmauricius\u002Fvue-draggable-resizable",rel:[e,f,g],target:h},children:[{type:a,value:"vue-draggable-resizable"}]},{type:a,value:" to get the desired feature, 2 powerful vue package. Uploaded images are stored as base 64 strings into a JSON, but I had to optimize them before to avoid storage limitations and to have the dragging-resizing tool perform better."}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"To do so, I directly send the file to "},{type:b,tag:c,props:{href:"https:\u002F\u002Fcloudinary.com\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Cloudinary"}]},{type:a,value:" which is a well-known cloud image management plateform. I can leverage some easy transformation operations on the fly such as resizing, cropping, and getting Exif meta-datas. Once done, the served file is converted as a base64 string."}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"At the last build step, the user is offered to send himself an image preview of the card he just built. I explore multiple ways but the most cross-browser reliable tool I found was "},{type:b,tag:c,props:{href:"https:\u002F\u002Fgithub.com\u002Fmycurelabs\u002Fvue-html2canvas",rel:[e,f,g],target:h},children:[{type:a,value:"vue-html2canvas"}]},{type:a,value:". This one generates a very neat image render of the DOM object passed."}]},{type:a,value:d},{type:b,tag:l,props:{id:y},children:[{type:b,tag:c,props:{href:"#deployment--lambdas-with-netlify",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:z}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"Regarding the hosting, I went with "},{type:b,tag:c,props:{href:"https:\u002F\u002Fnetlify.com\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Netlify"}]},{type:a,value:" once again, as it's definitely getting the number one platform to easily push web apps. Levaraging the "},{type:b,tag:c,props:{href:"https:\u002F\u002Fwww.netlify.com\u002Fproducts\u002Fdev\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Netlify dev CLI"}]},{type:a,value:", I now always deploy previews instead of the default publication workflow (Github continuous deployment). When I’m happy with the result, I just manually publish the deploy from the platform."}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"The emails sent are once again routed to Send In Blue SMTP using a "},{type:b,tag:c,props:{href:"https:\u002F\u002Fdocs.netlify.com\u002Ffunctions\u002Foverview\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Netlify lambda function"}]},{type:a,value:". I just adapted one of the many available node function boilerplates from "},{type:b,tag:c,props:{href:"https:\u002F\u002Fgithub.com\u002Fnetlify\u002Ffunctions",rel:[e,f,g],target:h},children:[{type:a,value:"this repository"}]},{type:a,value:". The greatness of Netlify function is that we can test them locally without having to deploy them. It’s out the box when we run the local server with \"ntl dev\" instead of \"npm run dev\". Deployment are done using \"ntl build\" then \"ntl deploy\"."}]},{type:a,value:d},{type:b,tag:l,props:{id:A},children:[{type:b,tag:c,props:{href:"#local-storages",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:B}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"In the future, user may save their customized card on a user account, and I will certainly go with "},{type:b,tag:c,props:{href:"https:\u002F\u002Ffirebase.google.com\u002Fproducts\u002Ffirestore",rel:[e,f,g],target:h},children:[{type:a,value:"Firestore"}]},{type:a,value:" & "},{type:b,tag:c,props:{href:"https:\u002F\u002Ffirebase.google.com\u002Fproducts\u002Fauth",rel:[e,f,g],target:h},children:[{type:a,value:"Firebase auth"}]},{type:a,value:". For the time being, we just have a local storage in the browser. At first, I used the classic "},{type:b,tag:c,props:{href:"https:\u002F\u002Fdeveloper.mozilla.org\u002Fen-US\u002Fdocs\u002FWeb\u002FAPI\u002FWindow\u002FlocalStorage",rel:[e,f,g],target:h},children:[{type:a,value:"localStorage API"}]},{type:a,value:", but quickly encountered errors because of the size limitation (especially in Safari) regarding the base 64 image strings. I then switched it for the "},{type:b,tag:c,props:{href:"https:\u002F\u002Fdeveloper.mozilla.org\u002Fen-US\u002Fdocs\u002FWeb\u002FAPI\u002FIndexedDB_API",rel:[e,f,g],target:h},children:[{type:a,value:"indexedDB API"}]},{type:a,value:". It’s way more powerful but also more complex to grasp, but at least, storage limitation is not a problem anymore."}]},{type:a,value:d},{type:b,tag:l,props:{id:C},children:[{type:b,tag:c,props:{href:"#unit-tests-and-end-2-end-tests",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:D}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"I finally wrote my first unit tests inside a real project after having postponed it for more than a year."}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"It seemed to me that shipping and maintaining such a tool without testing it before release it would have been very unsafe. It was time again for a very exhaustive reading on the subject : the "},{type:b,tag:c,props:{href:J,rel:[e,f,g],target:h},children:[{type:a,value:"Testing Vue.js applications book"}]},{type:a,value:", to catch things up in this domain. I just have a couple of tests using the "},{type:b,tag:c,props:{href:"https:\u002F\u002Fjestjs.io\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Jest framework"}]},{type:a,value:" combined with "},{type:b,tag:c,props:{href:"https:\u002F\u002Fvue-test-utils.vuejs.org\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Vue test utils"}]},{type:a,value:" which is the official Vue testing library. Not that difficult after all, but I still have to decide what to test beyond the obvious ones."}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"I also needed to test DOM elements presence outside Vue. I used "},{type:b,tag:c,props:{href:"https:\u002F\u002Fnightwatchjs.org\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Nightwatch"}]},{type:a,value:" as stated in the "},{type:b,tag:c,props:{href:J,rel:[e,f,g],target:h},children:[{type:a,value:"Edd Yerburgh’book"}]},{type:a,value:". The setup is pretty straightforward and is satisfying for my needs, even if I heard "},{type:b,tag:c,props:{href:"https:\u002F\u002Fwww.cypress.io\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Cypress"}]},{type:a,value:" is the today’s reference. Maybe later…"}]},{type:a,value:d},{type:b,tag:l,props:{id:E},children:[{type:b,tag:c,props:{href:"#git-workflow",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:F}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"As a solo dev, I’m not very rigid regarding my git workflow. Some features branch here and there but I mostly do my stuff on master. When the app will go live, I realized I would need something more robust. I just embraced the "},{type:b,tag:c,props:{href:"https:\u002F\u002Fwww.atlassian.com\u002Fgit\u002Ftutorials\u002Fcomparing-workflows\u002Fgitflow-workflow",rel:[e,f,g],target:h},children:[{type:a,value:"Gitflow"}]},{type:a,value:" workflow as it seems simple and a very good model to deliver releases in an organized way. Now I work on a develop branch + features branch, perform a pre-commit check (thanks to "},{type:b,tag:c,props:{href:"https:\u002F\u002Fgithub.com\u002Ftypicode\u002Fhusky",rel:[e,f,g],target:h},children:[{type:a,value:"Huski"}]},{type:a,value:") running test suites on “develop”, and tag each releases after having merging and pushing from master."}]},{type:a,value:d},{type:b,tag:l,props:{id:G},children:[{type:b,tag:c,props:{href:"#next",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:H}]},{type:a,value:d},{type:b,tag:i,props:{},children:[{type:a,value:"I learned a lot building this project and am probably half-way as I’ll have to implement user auth, PWA support, and a headless CMS to give hand to external contributors that will be able to change options. I Will probably go again with "},{type:b,tag:c,props:{href:"https:\u002F\u002Fprismic.io\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Prismic"}]},{type:a,value:" but that is another story."}]}]},excerpt:{type:I,children:[{type:b,tag:i,props:{},children:[{type:a,value:r}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Fcoding-a-custom-banking-card-creation-tool-with-nuxt",extension:".md",updatedAt:"2025-10-10T15:29:17.521Z"},relatedPosts:[{title:"Cinema 4D toon shading with Arnold render",type:j,imgCover:"cinema-4d-toon-shading-with-arnold-render-montpellier-gare-st-roch-trams-lines",tags:["cinema 4D","sketch & toon","after effects",j],createdAt:"2024-06-26T00:00:00.000Z",path:"\u002Fposts\u002Fcinema-4d-toon-shading-with-arnold-render"},{title:"Making a real time 3D scene with Sketchfab",type:j,imgCover:"making-a-real-time-3D-scene-with-the-sketchfab-viewer",tags:["cinema4D",K,j],createdAt:"2023-03-11T00:00:00.000Z",path:"\u002Fposts\u002Fmaking-a-real-time-3D-scene-with-the-sketchfab-viewer"},{title:"Weekx progressive web app",type:L,imgCover:"weekx-progressive-web-app",tags:["vue","vuex","pwa",t,L],createdAt:"2019-03-19T00:00:00.000Z",path:"\u002Fposts\u002Fweekx-progressive-web-app"},{title:"UI Prototypes with Protopie",type:j,imgCover:"ui-prototypes-with-protopie",tags:["Protopie","After Effects","Sketch",K,j],createdAt:"2021-05-18T00:00:00.000Z",path:"\u002Fposts\u002Fui-prototypes-with-protopie"}]}],fetch:[{counter:15},{counter:1},{counter:3},{counter:32},{counter:72}],mutations:[]}}("text","element","a","\n","nofollow","noopener","noreferrer","_blank","p","article",2,"h2","true",-1,"span","icon","icon-link","During the lockdown, and as the title speak for itself, I have started to work on a very interesting new project. it’s a multi-steps creation tool to build a customised banking card for almost every possible details.","coding-a-custom-banking-card-creation-tool-with-nuxt","devs","building-the-app","Building the app","image-handling","Image handling","deployment--lambdas-with-netlify","Deployment & lambdas with Netlify","local-storages","Local storage(s)","unit-tests-and-end-2-end-tests","Unit tests and end 2 end tests","git-workflow","Git workflow","next","Next","root","https:\u002F\u002Fwww.manning.com\u002Fbooks\u002Ftesting-vue-js-applications","miscs","design")));